import { Component, Element, Event, EventEmitter, h, Host, Prop, Watch } from '@stencil/core';

/**
 * @slot default - default slot for the content of the multiselect-option
 * @slot description - slot for descriptive text
 */
@Component({
  tag: 'groupui-multiselect-option',
  styleUrl: 'multiselect-option.scss',
  shadow: true,
})
export class MultiselectOption {
  /**
   * value of the multiselect-option to identify which option is selected.
   */
  @Prop({ reflect: true }) readonly value: string = Math.random().toString(36).substring(7);

  /**
   * checked status of the multiselect-option
   */
  @Prop({ mutable: true, reflect: true }) checked: boolean = false;

  /**
   * hidden attribute
   */
  @Prop({ reflect: true }) readonly indeterminate: boolean = false;

  /**
   * use this only with a searchable multiselect, hides the option
   */
  @Prop({ reflect: true }) readonly invisible: boolean = false;

  /**
   * this is the option which can select all others, use only one per multiselect
   */
  @Prop({ reflect: true }) readonly selectAll: boolean = false;

  /**
   * dispatched on checked change
   */
  @Event() checkedChanged: EventEmitter<HTMLElement>;

  @Element() host: HTMLElement;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  @Watch('checked')
  updateCheckProp() {
    this.checkedChanged.emit(this.host);
  }

  async componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  private isDescriptionSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="description"]');
  }

  render() {
    return (
      <Host tabIndex={-1}>
        <div>
          <groupui-checkbox
            tabIndex={-1}
            checked={this.checked}
            onChange={this.checkBoxChanged}
            id="container"
            indeterminate={this.indeterminate}
          >
            <span id="content">
              <slot />
              {this.isDescriptionSlotProvided() && <slot name="description" />}
            </span>
          </groupui-checkbox>
        </div>
      </Host>
    );
  }

  private checkBoxChanged = (event: Event) => {
    // eslint-disable-next-line no-undef
    this.checked = (event.target as HTMLGroupuiCheckboxElement).checked;
  };
}
